mkuse!{use rustc_middle :: ty :: { self , GenericArg , Ty , TyCtxt } ;}
mkitem!{mkstruct!{struct TypeNamePrinter < 'tcx > { tcx : TyCtxt < 'tcx > , path : String , }}}
mkitem!{mkimpl!{impl < 'tcx > Printer < 'tcx > for TypeNamePrinter < 'tcx > { fn tcx (& self) -> TyCtxt < 'tcx > { self . tcx } fn print_region (& mut self , _region : ty :: Region < '_ >) -> Result < () , PrintError > { write ! (self , "'_") } fn print_type (& mut self , ty : Ty < 'tcx >) -> Result < () , PrintError > { match * ty . kind () { ty :: Bool | ty :: Char | ty :: Int (_) | ty :: Uint (_) | ty :: Float (_) | ty :: Str | ty :: Pat (_ , _) | ty :: Array (_ , _) | ty :: Slice (_) | ty :: RawPtr (_ , _) | ty :: Ref (_ , _ , _) | ty :: FnPtr (..) | ty :: Never | ty :: Tuple (_) | ty :: Dynamic (_ , _ , _) | ty :: UnsafeBinder (_) => self . pretty_print_type (ty) , ty :: Param (_) | ty :: Bound (..) | ty :: Placeholder (_) | ty :: Infer (_) | ty :: Error (_) => { write ! (self , "_") ? ; Ok (()) } ty :: Adt (ty :: AdtDef (Interned (& ty :: AdtDefData { did : def_id , .. } , _)) , args) | ty :: FnDef (def_id , args) | ty :: Alias (ty :: Projection | ty :: Opaque , ty :: AliasTy { def_id , args , .. }) | ty :: Closure (def_id , args) | ty :: CoroutineClosure (def_id , args) | ty :: Coroutine (def_id , args) => self . print_def_path (def_id , args) , ty :: Foreign (def_id) => self . print_def_path (def_id , & []) , ty :: Alias (ty :: Free , _) => bug ! ("type_name: unexpected free alias") , ty :: Alias (ty :: Inherent , _) => bug ! ("type_name: unexpected inherent projection") , ty :: CoroutineWitness (..) => bug ! ("type_name: unexpected `CoroutineWitness`") , } } fn print_const (& mut self , ct : ty :: Const < 'tcx >) -> Result < () , PrintError > { self . pretty_print_const (ct , false) } fn print_dyn_existential (& mut self , predicates : & 'tcx ty :: List < ty :: PolyExistentialPredicate < 'tcx > > ,) -> Result < () , PrintError > { self . pretty_print_dyn_existential (predicates) } fn print_crate_name (& mut self , cnum : CrateNum) -> Result < () , PrintError > { self . path . push_str (self . tcx . crate_name (cnum) . as_str ()) ; Ok (()) } fn print_path_with_qualified (& mut self , self_ty : Ty < 'tcx > , trait_ref : Option < ty :: TraitRef < 'tcx > > ,) -> Result < () , PrintError > { self . pretty_print_path_with_qualified (self_ty , trait_ref) } fn print_path_with_impl (& mut self , print_prefix : impl FnOnce (& mut Self) -> Result < () , PrintError > , self_ty : Ty < 'tcx > , trait_ref : Option < ty :: TraitRef < 'tcx > > ,) -> Result < () , PrintError > { self . pretty_print_path_with_impl (| cx | { print_prefix (cx) ? ; cx . path . push_str ("::") ; Ok (()) } , self_ty , trait_ref ,) } fn print_path_with_simple (& mut self , print_prefix : impl FnOnce (& mut Self) -> Result < () , PrintError > , disambiguated_data : & DisambiguatedDefPathData ,) -> Result < () , PrintError > { print_prefix (self) ? ; write ! (self . path , "::{}" , disambiguated_data . data) . unwrap () ; Ok (()) } fn print_path_with_generic_args (& mut self , print_prefix : impl FnOnce (& mut Self) -> Result < () , PrintError > , args : & [GenericArg < 'tcx >] ,) -> Result < () , PrintError > { print_prefix (self) ? ; if ! args . is_empty () { self . generic_delimiters (| cx | cx . comma_sep (args . iter () . copied ())) } else { Ok (()) } } fn print_coroutine_with_kind (& mut self , def_id : DefId , parent_args : & 'tcx [GenericArg < 'tcx >] , kind : Ty < 'tcx > ,) -> Result < () , PrintError > { self . print_def_path (def_id , parent_args) ? ; let ty :: Coroutine (_ , args) = self . tcx . type_of (def_id) . instantiate_identity () . kind () else { return Ok (()) ; } ; let default_kind = args . as_coroutine () . kind_ty () ; match kind . to_opt_closure_kind () { _ if kind == default_kind => { } Some (ty :: ClosureKind :: Fn) | None => { } Some (ty :: ClosureKind :: FnMut) => self . path . push_str ("::{{call_mut}}") , Some (ty :: ClosureKind :: FnOnce) => self . path . push_str ("::{{call_once}}") , } Ok (()) } }}}
mkitem!{mkimpl!{impl < 'tcx > PrettyPrinter < 'tcx > for TypeNamePrinter < 'tcx > { fn should_print_optional_region (& self , region : ty :: Region < '_ >) -> bool { let kind = region . kind () ; match region . kind () { ty :: ReErased | ty :: ReEarlyParam (_) | ty :: ReStatic => false , ty :: ReBound (..) => true , _ => panic ! ("type_name unhandled region: {kind:?}") , } } fn generic_delimiters (& mut self , f : impl FnOnce (& mut Self) -> Result < () , PrintError > ,) -> Result < () , PrintError > { write ! (self , "<") ? ; f (self) ? ; write ! (self , ">") ? ; Ok (()) } fn should_print_verbose (& self) -> bool { false } }}}
mkitem!{mkimpl!{impl Write for TypeNamePrinter < '_ > { fn write_str (& mut self , s : & str) -> std :: fmt :: Result { self . path . push_str (s) ; Ok (()) } }}}

macro_rules! type_name_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function type_name in module {}", module_path!());
    };
}

mkfn!{
    type_name_introspect!();
    pub fn type_name < 'tcx > (tcx : TyCtxt < 'tcx > , ty : Ty < 'tcx >) -> String { let mut p = TypeNamePrinter { tcx , path : String :: new () } ; p . print_type (ty) . unwrap () ; p . path }
}